import {readFileSync,writeFileSync} from 'node:fs';
const source=readFileSync('.git/b11-core-lifetime-audit.ts','utf8');
const substitutions=[['missing-disposal',"source.replace('using statement = this.db.prepare<', 'const statement = this.db.prepare<')"],['unscoped-helper',"source.replace('using insertStatement = this.prepareInsert()', 'const insertStatement = this.prepareInsert()')"],['cached-query',"source.replace('using statement = this.db.prepare<MessageRow, [string]>', 'using statement = this.db.query<MessageRow, [string]>')"]];
const runs=[];
for(const [name,expression]of substitutions){
 const injected=source.replace("const source=readFileSync(entry.path,'utf8'),file=",`const raw=readFileSync(entry.path,'utf8'),source=entry.path.endsWith('/message-repository.ts')?((source:string)=>${expression})(raw):raw,file=`);
 if(injected===source)throw Error('No audit fault injected');
 writeFileSync('.git/b11-core-lifetime-negative.ts',injected);
 const child=Bun.spawnSync([process.execPath,'.git/b11-core-lifetime-negative.ts'],{stdout:'pipe',stderr:'pipe',timeout:30000});
 const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
 if(child.exitCode!==1||!/(Unowned native prepare|Unscoped helper|Retained statement\/query remains)/.test(output))throw Error('Audit fault was not rejected '+output);
 runs.push({name,exit:child.exitCode,output,source:injected});
}
writeFileSync('.git/b11-core-lifetime-negative.json',JSON.stringify({runs,source:readFileSync('.git/b11-core-lifetime-negative-checks.ts','utf8')},null,2)+'\n');console.log(JSON.stringify(runs.map(({name,exit})=>({name,exit}))));

